
UPDATE courses SET
    course_description = '<p style="text-align:justify;">This qualification reflects the role of pathology collectors. Workers in this role follow known routines and procedures, taking responsibility for their own work under general supervision. They combine communication, customer service and technical skills, and use discretion and judgment to adapt and transfer their skills to different situations.</p> <p style="text-align:justify;">To achieve this qualification, the candidate must have completed at least 35 hours of work as detailed in the Assessment Requirements of units of competency.</p> <p style="text-align:justify;">No licensing, legislative, regulatory or certification requirements apply to this qualification at the time of publication.</p>',
    total_course_duration = '36 Weeks',
    offshore_tuition_fee = '',
    entry_requirements = '<p>The following are the Admission requirements of Lead college:</p> <li>Must be 18 years of age or older at the time of course commencement.</li> <li>Prospective students may be required to undertake a Language, Literacy and Numeracy (LLN) and/or a pre-enrolment interview.</li> <li>Must have completed Australian Year 11 or equivalent level of schooling or a Certificate III or higher qualification with an Australian institution.</li> <li>Must demonstrate English level of IELTS 6.0 overall with no band less than 5.5 or equivalent, such as: <ul> <li>IBT 60</li> <li>PTE 50</li> <li>CAE 169</li> <li>OET B</li> <li>General English Advanced or equivalent</li> <li>MOI Certificate</li> <li>Duolingo 95</li> <li>MET </li> <li>LANGUAGECERT Academic </li> <li>CELPIP General</li> <li>Certificate IV or higher qualification with an Australian institution.</li> </ul> </li> <li>IBT 60</li> <li>PTE 50</li> <li>CAE 169</li> <li>OET B</li> <li>General English Advanced or equivalent</li> <li>MOI Certificate</li> <li>Duolingo 95</li> <li>MET </li> <li>LANGUAGECERT Academic </li> <li>CELPIP General</li> <li>Certificate IV or higher qualification with an Australian institution.</li> <li>Must have basic digital literacy, including the ability to confidently use the internet and common software applications for learning purposes, completing assignments, and engaging with course content.</li> <li>Must be able to participate in training within a simulated workplace environment, including performing manual handling tasks.</li>',
    apply_form = 'https://www.leadcollege.edu.au/courses/certificate-iii-in-pathology-collection/',
    updated_at = NOW()
WHERE cricos_course_code = '108756C';


UPDATE courses SET
    course_description = '<p style="text-align:justify;">This qualification reflects pre-hospital and out-of-hospital workers employed to provide patient assessment, healthcare and transport services. These workers possess clinical skills and theoretical knowledge and provide clinical assessment and pre-hospital and out-of-hospital interventions to patients in an emergency, including providing advanced skills in life support. This qualification applies to a variety of roles within the health care and patient transport system.</p> <p style="text-align:justify;">To achieve this qualification, the candidate must have completed at least 160 hours of work as detailed in the Assessment Requirements of Units of Competency.</p> <p style="text-align:justify;">No occupational licensing, certification or specific legislative requirements apply to this qualification at the time of publication.</p>',
    total_course_duration = '78 Weeks',
    offshore_tuition_fee = '',
    entry_requirements = '<p>The following are the Admission requirements of Lead college:</p> <li>Must be 18 years of age or older at the time of course commencement.</li> <li>Prospective students may be required to undertake a Language, Literacy and Numeracy (LLN) and/or a pre-enrolment interview.</li> <li>Must have completed Australian Year 12 or equivalent level of schooling or a Certificate III or higher qualification with an Australian institution.</li> <li>Must demonstrate English level of IELTS 6.0 overall with no band less than 5.5 or equivalent, such as: <ul> <li>IBT 60</li> <li>PTE 50</li> <li>CAE 169</li> <li>OET B</li> <li>General English Advanced or equivalent</li> <li>MOI Certificate</li> <li>Duolingo 95</li> <li>MET </li> <li>LANGUAGECERT Academic </li> <li>CELPIP General</li> <li>Certificate IV or higher qualification with an Australian institution.</li> </ul> </li> <li>IBT 60</li> <li>PTE 50</li> <li>CAE 169</li> <li>OET B</li> <li>General English Advanced or equivalent</li> <li>MOI Certificate</li> <li>Duolingo 95</li> <li>MET </li> <li>LANGUAGECERT Academic </li> <li>CELPIP General</li> <li>Certificate IV or higher qualification with an Australian institution.</li> <li>Must have basic digital literacy, including the ability to confidently use the internet and common software applications for learning purposes, completing assignments, and engaging with course content.</li> <li>Must be able to participate in training within a simulated workplace environment, including performing manual handling tasks.</li> <li>Must be eligible to drive in New South Wales (NSW)/Western Australia. A valid NSW/WA driver’s licence is required within 3 months of the course commencement.</li>',
    apply_form = 'https://www.leadcollege.edu.au/courses/diploma-of-emergency-health-care/',
    updated_at = NOW()
WHERE cricos_course_code = '108757B';


UPDATE courses SET
    course_description = '<p style="text-align:justify;">This qualification reflects the role of individuals who provide person-centred support in community, home, or residential care settings. They work under supervision and delegation as part of a multidisciplinary team, following an individualised support plan to assist people who may need help due to ageing, disability, or other reasons.</p> <p style="text-align:justify;">These workers are responsible for their own work outcomes within the boundaries of their role and delegated tasks. They apply a broad range of factual, technical, and procedural knowledge, along with some theoretical understanding, to deliver effective person-centred care.</p> <p style="text-align:justify;">All skills developed through this qualification must be applied in line with relevant Commonwealth and State or Territory legislation, Australian standards, and industry codes of practice.</p> <p style="text-align:justify;">No licensing, legislative, regulatory or certification requirements apply to this qualification at the time of publication.</p>',
    total_course_duration = '52 Weeks',
    offshore_tuition_fee = '',
    entry_requirements = '<p>The following are the Admission requirements of Lead college:</p> <li>Must be 18 years of age or older at the time of course commencement.</li> <li>Prospective students may be required to undertake a Language, Literacy and Numeracy (LLN) and/or a pre-enrolment interview.</li> <li>Must have completed Australian Year 11 or equivalent level of schooling or a Certificate III or higher qualification with an Australian institution.</li> <li>Must demonstrate English level of IELTS 6.0 overall with no band less than 5.5 or equivalent, such as: <ul> <li>IBT 60</li> <li>PTE 50</li> <li>CAE 169</li> <li>OET B</li> <li>General English Advanced or equivalent</li> <li>MOI Certificate</li> <li>Duolingo 95</li> <li>MET </li> <li>LANGUAGECERT Academic </li> <li>CELPIP General</li> <li>Certificate IV or higher qualification with an Australian institution.</li> </ul> </li> <li>IBT 60</li> <li>PTE 50</li> <li>CAE 169</li> <li>OET B</li> <li>General English Advanced or equivalent</li> <li>MOI Certificate</li> <li>Duolingo 95</li> <li>MET </li> <li>LANGUAGECERT Academic </li> <li>CELPIP General</li> <li>Certificate IV or higher qualification with an Australian institution.</li> <li>Must have basic digital literacy, including the ability to confidently use the internet and common software applications for learning purposes, completing assignments, and engaging with course content.</li> <li>Must be able to participate in training within a simulated workplace environment, including performing manual handling tasks.</li>',
    apply_form = 'https://www.leadcollege.edu.au/courses/cert-iii-individual-support/',
    updated_at = NOW()
WHERE cricos_course_code = '112470E';


UPDATE courses SET
    course_description = '<p style="text-align:justify;">This qualification reflects the role of individuals who provide support to people with disabilities across a variety of community settings and in clients’ homes. The focus is on empowering individuals to enhance their independence, self-reliance, community participation, and overall wellbeing.</p> <p style="text-align:justify;">Workers adopt a person-centred approach, follow individualised support plans, and may contribute to their development. They work autonomously and may also be responsible for supervising or coordinating a small team.</p> <p style="text-align:justify;">All skills must be applied in accordance with relevant Commonwealth and State/Territory legislation, Australian standards, and industry codes of practice.</p> <p style="text-align:justify;">No licensing, legislative, regulatory or certification requirements apply to this qualification at the time of publication.</p>',
    total_course_duration = '52 Weeks',
    offshore_tuition_fee = '',
