UPDATE courses SET
    course_description = '<p style="text-align:justify;">This qualification reflects the role of support workers who carry out specialised tasks and functions in aged care services across residential, home, or community-based settings. These workers operate within established organisational guidelines, taking responsibility for their own performance and ensuring high-quality service delivery through the development, facilitation, and review of individualised care plans.</p> <p style="text-align:justify;">In some cases, workers may be required to demonstrate leadership and take limited responsibility for the supervision and output quality of others, within defined parameters.</p>',
