UPDATE courses SET
    course_description = '<p style="text-align:justify;">This qualification reflects the role of community services workers involved in the delivery, management and coordination of person-centred services to individuals, groups, and communities.</p> <p style="text-align:justify;">At this level, workers have specialised skills in community services and work autonomously within their scope of practice under broad directions from senior management.</p> <p style="text-align:justify;">Workers support people to make change in their lives to improve personal and social wellbeing and may also have responsibility for the supervision of other workers and volunteers. They may also undertake case management and program coordination.</p> <p style="text-align:justify;">To achieve this qualification, the candidate must have completed at least 400 hours of work placement as detailed in the Assessment Requirements of units of competency.</p> <p style="text-align:justify;">The skills in this qualification must be applied in accordance with Commonwealth and State or Territory legislation, Australian standards and industry codes of practice.</p> <p style="text-align:justify;">No occupational licensing, certification or specific legislative requirements apply to this qualification at the time of publication.</p>',
