UPDATE courses SET
    course_description = '<p style="text-align:justify;">This qualification reflects the role of educators in early childhood education and care who work in regulated children’s education and care services in Australia. They support children’s wellbeing, and development in the context of an approved learning framework. Educators use a range of well-developed skills and knowledge using discretion and judgment when carrying out their work in the context of established policies and procedures. They may work independently or under the guidance of others, though in some contexts that guidance may not be on-site.</p> <p style="text-align:justify;">Early childhood educators work in long day care centres, family day care, pre-schools or kindergartens.</p> <p style="text-align:justify;">To achieve this qualification, the individual must have completed a total of at least 160 hours of work in a regulated children’s education and care service in Australia as detailed in the Assessment Requirements of units of competency. The total number of hours may be applied collectively across all units of competency that include the requirement for workplace hours.</p> <p style="text-align:justify;">There are 160 minimum work placement hours required for this unit.</p> <p style="text-align:justify;">Under the Education and Care Services National Law (as applied in each state and territory) the Australian Children’s Education and Care Quality Authority (ACECQA) publishes lists of approved early childhood education and care qualifications and information regarding regulatory requirements here: <a href="www.acecqa.gov.au" target="_blank">www.acecqa.gov.au</a>.</p>',
    total_course_duration = '52 Weeks',
    offshore_tuition_fee = '',
    entry_requirements = '<p>The following are the Admission requirements of Lead college:</p> <li>Must be 18 years of age or older at the time of course commencement.</li> <li>Prospective students may be required to undertake a Language, Literacy and Numeracy (LLN) and/or a pre-enrolment interview.</li> <li>Must have completed Australian Year 11 or equivalent level of schooling or a Certificate III or higher qualification with an Australian institution.</li> <li>Must demonstrate English level of IELTS 6.0 overall with no band less than 5.5 or equivalent, such as: <ul> <li>IBT 60</li> <li>PTE 50</li> <li>CAE 169</li> <li>OET B</li> <li>General English Advanced or equivalent</li> <li>MOI Certificate</li> <li>Duolingo 95</li> <li>MET </li> <li>LANGUAGECERT Academic </li> <li>CELPIP General</li> <li>Certificate IV or higher qualification with an Australian institution.</li> </ul> </li> <li>IBT 60</li> <li>PTE 50</li> <li>CAE 169</li> <li>OET B</li> <li>General English Advanced or equivalent</li> <li>MOI Certificate</li> <li>Duolingo 95</li> <li>MET </li> <li>LANGUAGECERT Academic </li> <li>CELPIP General</li> <li>Certificate IV or higher qualification with an Australian institution.</li> <li>Must have basic digital literacy, including the ability to confidently use the internet and common software applications for learning purposes, completing assignments, and engaging with course content.</li> <li>Must be able to participate in training within a simulated workplace environment, including performing manual handling tasks.</li>',
    apply_form = 'https://www.leadcollege.edu.au/courses/certificate-iii-in-early-childhood-education-and-care/',
    updated_at = NOW()
WHERE cricos_course_code = '119778F';


UPDATE courses SET
    course_description = '<p style="text-align:justify;">This qualification reflects the role of educators in early childhood education and care working within regulated children’s education and care services across Australia. Educators at this level are responsible for designing and implementing curriculum that aligns with an approved learning framework, as well as ensuring compliance with other service operational requirements.</p> <p style="text-align:justify;">They apply specialised knowledge and critically analyse theoretical concepts to effectively address diverse work situations. Additionally, they may hold supervisory responsibilities over volunteers or other educators.</p> <p style="text-align:justify;">Early childhood educators are employed in settings such as long day care centres, family day care, preschools, and kindergartens.</p> <p style="text-align: justify;">No occupational licensing, certification or specific legislative requirements apply to this qualification at the time of publication. </p> <p style="text-align: justify;">Under the Education and Care Services National Law (2011) the Australian Children’s Education and Care Quality Authority (ACECQA) publishes lists of approved early childhood education and care qualifications and information regarding regulatory requirements here: <a href="www.acecqa.gov.au" target="_blank">www.acecqa.gov.au</a></p>',
    total_course_duration = '56 Weeks',
    offshore_tuition_fee = '',
    entry_requirements = '<p>The following are the admission requirements of Lead college: <ul> <li>Must be 18 years of age or older at the time of course commencement.</li> <li>Prospective students may be required to undertake a Language, Literacy and Numeracy (LLN) and/or a pre-enrolment interview.</li> <li><p style="color:black;">hold a CHC30121 Certificate III in Early Childhood Education and Care or CHC30113 Certificate III in Early Childhood Education and Care Lead College or another institute with similar elective. Alternatively, individuals may hold:</p> <p style="color:black;">An Australian diploma in Early Childhood Education and Care</p> OR <p style="color:black;">An Australian diploma or certificate III in Children’s Services.</p> AND <p style="color:black;">Demonstrate at least 12 months of cumulative employment (full-time equivalent) within the last 5 years in a regulated education and care service in Australia, supported by verifiable evidence.</p> OR <p style="color:black;">Hold the CHCSS00147 Entry into Diploma of Early Childhood Education and Care.</p></li> <li>Must demonstrate English level of IELTS 6.0 overall with no band less than 5.5 or equivalent, such as: <ul> <li>IBT 60</li> <li>PTE 50</li> <li>CAE 169</li> <li>OET B</li> <li>General English Advanced or equivalent</li> <li>MOI Certificate</li> <li>Duolingo 95</li> <li>MET</li> <li>LANGUAGECERT Academic</li> <li>CELPIP General</li> <li>Certificate IV or higher qualification with an Australian institution.</li> </ul> </li> <li>Must have basic digital literacy, including the ability to confidently use the internet and common software applications for learning purposes, completing assignments, and engaging with course content.</li> <li>Must be able to participate in training within a simulated workplace environment, including performing manual handling tasks.</li> </ul> </p> <li>Must be 18 years of age or older at the time of course commencement.</li> <li>Prospective students may be required to undertake a Language, Literacy and Numeracy (LLN) and/or a pre-enrolment interview.</li> <li><p style="color:black;">hold a CHC30121 Certificate III in Early Childhood Education and Care or CHC30113 Certificate III in Early Childhood Education and Care Lead College or another institute with similar elective. Alternatively, individuals may hold:</p> <p style="color:black;">An Australian diploma in Early Childhood Education and Care</p> OR <p style="color:black;">An Australian diploma or certificate III in Children’s Services.</p> AND <p style="color:black;">Demonstrate at least 12 months of cumulative employment (full-time equivalent) within the last 5 years in a regulated education and care service in Australia, supported by verifiable evidence.</p> OR <p style="color:black;">Hold the CHCSS00147 Entry into Diploma of Early Childhood Education and Care.</p></li> <p style="color:black;">hold a CHC30121 Certificate III in Early Childhood Education and Care or CHC30113 Certificate III in Early Childhood Education and Care Lead College or another institute with similar elective. Alternatively, individuals may hold:</p> <p style="color:black;">An Australian diploma in Early Childhood Education and Care</p> <p style="color:black;">An Australian diploma or certificate III in Children’s Services.</p> <p style="color:black;">Demonstrate at least 12 months of cumulative employment (full-time equivalent) within the last 5 years in a regulated education and care service in Australia, supported by verifiable evidence.</p> <p style="color:black;">Hold the CHCSS00147 Entry into Diploma of Early Childhood Education and Care.</p> <li>Must demonstrate English level of IELTS 6.0 overall with no band less than 5.5 or equivalent, such as: <ul> <li>IBT 60</li> <li>PTE 50</li> <li>CAE 169</li> <li>OET B</li> <li>General English Advanced or equivalent</li> <li>MOI Certificate</li> <li>Duolingo 95</li> <li>MET</li> <li>LANGUAGECERT Academic</li> <li>CELPIP General</li> <li>Certificate IV or higher qualification with an Australian institution.</li> </ul> </li> <li>IBT 60</li> <li>PTE 50</li> <li>CAE 169</li> <li>OET B</li> <li>General English Advanced or equivalent</li> <li>MOI Certificate</li> <li>Duolingo 95</li> <li>MET</li> <li>LANGUAGECERT Academic</li> <li>CELPIP General</li> <li>Certificate IV or higher qualification with an Australian institution.</li> <li>Must have basic digital literacy, including the ability to confidently use the internet and common software applications for learning purposes, completing assignments, and engaging with course content.</li> <li>Must be able to participate in training within a simulated workplace environment, including performing manual handling tasks.</li>',
    apply_form = 'https://www.leadcollege.edu.au/courses/diploma-of-early-childhood-education-and-care/',
    updated_at = NOW()
