UPDATE courses SET
    course_description = '<p style="text-align: justify;">This qualification reflects the trade qualified role of a bricklayer, blocklayer or paver who may have responsibility for undertaking heritage bricklaying, refractory bricklaying, bricklaying, blocklaying and paving work in residential, industrial and commercial contexts, in both existing and new constructions.</p> <p style="text-align: justify;">Occupational titles may include: <ul> <li>Bricklayer</li> <li>Blocklayer</li> <li>Paver</li> </ul> </p> <li>Bricklayer</li> <li>Blocklayer</li> <li>Paver</li> <p style="text-align: justify;">The bricklaying, blocklaying and paving industry strongly affirms that training and assessment leading to recognition of skills must be undertaken in a real or closely simulated workplace environment and this qualification requires all units of competency to be delivered and assessed in this context.</p> <p style="text-align: justify;">Licensing, legislative, regulatory and certification requirements vary between states. Relevant state and territory regulatory authorities should be consulted to confirm those requirements.</p> <p style="text-align: justify;">Completion of the general construction induction training program, specified in the Safe Work Australia model Code of Practice: Construction Work, is required by anyone carrying out construction work. Achievement of CPCCWHS1001 Prepare to work safely in the construction industry meets this requirement.</p> <p style="text-align: justify;">No pre-requisite requirement for this qualification as per course training package.</p>',
    total_course_duration = '94 Weeks',
    offshore_tuition_fee = '',
