UPDATE courses SET
    course_description = '<p style="text-align: justify;">This qualification reflects the role of individuals who apply specialised knowledge and skills, together with experience in leadership and management, across a range of enterprise and industry contexts.</p> <p style="text-align: justify;">Individuals at this level use initiative and judgement to plan and implement a range of leadership and management functions, with accountability for personal and team outcomes within broad parameters.</p> <p style="text-align: justify;">They use cognitive and communication skills to identify, analyse and synthesise information from a variety of sources and transfer their knowledge to others, and creative or conceptual skills to express ideas and perspectives or respond to complex problems.</p>',
    total_course_duration = '52 Weeks',
    offshore_tuition_fee = '',
    entry_requirements = '<p>The following are the Admission requirements of Lead college:</p> <li>Must be 18 years of age or older at the time of course commencement.</li> <li>Prospective students may be required to undertake a Language, Literacy and Numeracy (LLN) and/or a pre-enrolment interview.</li> <li>Must have completed a Diploma or Advanced Diploma from the BSB Training Package (current or superseded equivalent versions) Lead College or another institute with similar elective. Or have two years equivalent full-time relevant workplace experience in an operational or leadership role in an enterprise.</li> <li>Must demonstrate English level of IELTS 6.0 overall with no band less than 5.5 or equivalent, such as: <ul> <li>IBT 60</li> <li>PTE 50</li> <li>CAE 169</li> <li>OET B</li> <li>General English Advanced or equivalent</li> <li>MOI Certificate</li> <li>Duolingo 95</li> <li>MET </li> <li>LANGUAGECERT Academic </li> <li>CELPIP General</li> <li>Certificate IV or higher qualification with an Australian institution.</li> </ul> </li> <li>IBT 60</li> <li>PTE 50</li> <li>CAE 169</li> <li>OET B</li> <li>General English Advanced or equivalent</li> <li>MOI Certificate</li> <li>Duolingo 95</li> <li>MET </li> <li>LANGUAGECERT Academic </li> <li>CELPIP General</li> <li>Certificate IV or higher qualification with an Australian institution.</li> <li>Must have basic digital literacy, including the ability to confidently use the internet and common software applications for learning purposes, completing assignments, and engaging with course content.</li> <li>Must be able to participate in training within a simulated workplace environment, including performing manual handling tasks.</li>',
