UPDATE courses SET
    course_description = '<p style="text-align:justify;">This qualification reflects the role of chefs and cooks who have a supervisory or team leading role in the kitchen. They operate independently or with limited guidance from others and use discretion to solve non-routine problems.</p> <p style="text-align:justify;">This qualification provides a pathway to work in organisations such as restaurants, hotels, clubs, pubs, cafes and coffee shops, or to run a small business in these sectors.</p> <p style="text-align:justify;">The skills in this qualification must be applied in accordance with Commonwealth and State or Territory legislation, Australian standards and industry codes of practice.</p> <p style="text-align:justify;">No occupational licensing, certification or specific legislative requirements apply to this qualification at the time of publication.</p>',
    total_course_duration = '80 Weeks',
    offshore_tuition_fee = '',
