    course_description = '<p style="text-align:justify;">Target Groups for SIT60322 – Advanced Diploma of Hospitality Management</p> <p style="text-align:justify;">This qualification is designed for students who are: <ul> <li>Aspiring to develop a career as a Conference and Event Organiser.</li> <li>Seeking a pathway into higher education qualifications in hospitality management and related disciplines.</li> </ul> </p> <li>Aspiring to develop a career as a Conference and Event Organiser.</li> <li>Seeking a pathway into higher education qualifications in hospitality management and related disciplines.</li> <p style="text-align:justify;"> No occupational licensing, certification or specific legislative requirements apply to this qualification at the time of publication. </p>',
