UPDATE courses SET
    course_description = '<p style="text-align: justify;">This qualification outlines the skills and knowledge required to work as an Engineering Tradesperson – Fabrication within the metal, engineering, manufacturing, and related industries. It has been specifically developed to meet the needs of apprentices/Learners in this trade.</p> <p style="text-align: justify;">This qualification is delivered in consultation with industry professionals to ensure it meets current industry standards and practices.</p> <p style="text-align: justify;">The skills covered are applicable to a broad range of fabrication work, including metal fabrication, structural steel erection, sheet metal work, welding, blacksmithing, and surface finishing.</p> <p style="text-align: justify;">This qualification provides an industry-recognised skills profile aligned with the trade-level responsibilities of an Engineering Tradesperson – Fabrication.</p> <p style="text-align: justify;">Where specified, assessment of certain units must be conducted in a functioning workplace with access to a sufficient range of tasks and materials to ensure the scope and standard of performance reflect real industry conditions.</p> <p style="text-align: justify;">No licensing, legislative or certification requirements apply to this qualification at the time of publication. Local regulations should be checked.</p>',
    total_course_duration = '70 Weeks',
    offshore_tuition_fee = '',
    entry_requirements = '<p>The following are the Admission requirements of Lead college:</p> <li>Must be 18 years of age or older at the time of course commencement.</li> <li>Prospective students may be required to undertake a Language, Literacy and Numeracy (LLN) and/or a pre-enrolment interview.</li> <li>Must have completed Australian Year 11 or equivalent level of schooling or a Certificate III or higher qualification with an Australian institution.</li> <li>Must demonstrate English level of IELTS 6.0 overall with no band less than 5.5 or equivalent, such as: <ul> <li>IBT 60</li> <li>PTE 50</li> <li>CAE 169</li> <li>OET B</li> <li>General English Advanced or equivalent</li> <li>Duolingo 95</li> <li>MET </li> <li>LANGUAGECERT Academic </li> <li>CELPIP General</li> <li>Certificate IV or higher qualification with an Australian institution.</li> </ul> </li> <li>IBT 60</li> <li>PTE 50</li> <li>CAE 169</li> <li>OET B</li> <li>General English Advanced or equivalent</li> <li>Duolingo 95</li> <li>MET </li> <li>LANGUAGECERT Academic </li> <li>CELPIP General</li> <li>Certificate IV or higher qualification with an Australian institution.</li> <li>Must have basic digital literacy, including the ability to confidently use the internet and common software applications for learning purposes, completing assignments, and engaging with course content.</li> <li>Must be able to participate in training within a simulated workplace environment, including performing manual handling tasks.</li>',
    apply_form = 'https://www.leadcollege.edu.au/courses/certificate-iii-in-engineering-fabrication-trade/',
    updated_at = NOW()
WHERE cricos_course_code = '119011J';


UPDATE courses SET
    course_description = '<p style="text-align: justify;">This qualification defines the skills and knowledge required of a higher-level engineering tradesperson within the metal, engineering, manufacturing, and related industries.</p> <p style="text-align: justify;">It applies to a broad range of advanced engineering work, including but not limited to: refrigeration and air conditioning, casting and moulding, CNC programming, fluid power, heavy fabrication, instrumentation, maintenance, plant mechanics, marine electronics, mechatronics, patternmaking, robotics, toolmaking, welding, and watch and clock servicing and repair. This may also include post-trade work.</p> <p style="text-align: justify;">Graduates will gain the capability to: <ul> <li>Apply quality control techniques</li> <li>Interpret complex instructions and procedures</li> <li>Work independently or as part of a team with minimal supervision</li> <li>Use effective interpersonal and communication skills</li> <li>Exercise discretion and judgement within defined responsibilities</li> <li>Guide and assist others in a trade environment</li> <li>Perform incidental non-trade tasks supporting primary duties</li> <li>Inspect materials and products for compliance with standards</li> <li>Operate lifting equipment related to their tasks</li> <li>Support training delivery alongside supervisors and trainers</li> </ul> </p> <li>Apply quality control techniques</li> <li>Interpret complex instructions and procedures</li> <li>Work independently or as part of a team with minimal supervision</li> <li>Use effective interpersonal and communication skills</li> <li>Exercise discretion and judgement within defined responsibilities</li> <li>Guide and assist others in a trade environment</li> <li>Perform incidental non-trade tasks supporting primary duties</li> <li>Inspect materials and products for compliance with standards</li> <li>Operate lifting equipment related to their tasks</li> <li>Support training delivery alongside supervisors and trainers</li> <p style="text-align: justify;">While there are no formal entry requirements, it is expected that learners are qualified tradespeople with access to structured on- and off-the-job training, or apprentices under an Australian Apprenticeship arrangement. This qualification is not intended for pre-employment or pre-apprenticeship use.</p> <p style="text-align:justify;">No licensing, legislative or certification requirements apply to this qualification at the time of publication. However, in some jurisdictions units in this qualification may require a license. Licensing information is included in the relevant units of competency.</p>',
    total_course_duration = '104 Weeks',
    offshore_tuition_fee = '',
    entry_requirements = '<p>The following are the Admission requirements of Lead college:</p> <li>Must be 18 years of age or older at the time of course commencement.</li> <li>Prospective students may be required to undertake a Language, Literacy and Numeracy (LLN) and/or a pre-enrolment interview.</li> <li>Must have completed MEM31922 Certificate III in Engineering – Fabrication Trade with Lead College or another institute with similar elective.</li> <li>Must demonstrate English level of IELTS 6.0 overall with no band less than 5.5 or equivalent, such as: <ul> <li>IBT 60</li> <li>PTE 50</li> <li>CAE 169</li> <li>OET B</li> <li>General English Advanced or equivalent</li> <li>MOI Certificate</li> <li>Duolingo 95</li> <li>MET </li> <li>LANGUAGECERT Academic </li> <li>CELPIP General</li> <li>Certificate IV or higher qualification with an Australian institution.</li> </ul> </li> <li>IBT 60</li> <li>PTE 50</li> <li>CAE 169</li> <li>OET B</li> <li>General English Advanced or equivalent</li> <li>MOI Certificate</li> <li>Duolingo 95</li> <li>MET </li> <li>LANGUAGECERT Academic </li> <li>CELPIP General</li> <li>Certificate IV or higher qualification with an Australian institution.</li> <li>Must have basic digital literacy, including the ability to confidently use the internet and common software applications for learning purposes, completing assignments, and engaging with course content.</li> <li>Must be able to participate in training within a simulated workplace environment, including performing manual handling tasks.</li>',
    apply_form = 'https://www.leadcollege.edu.au/courses/certificate-iv-in-engineering/',
    updated_at = NOW()
WHERE cricos_course_code = '112672F';


