UPDATE courses SET
    course_description = '<p style="text-align:justify;">This unit describes the skills and knowledge required to provide a first aid response to infants and children in line with first aid guidelines determined by the Australian Resuscitation Council (ARC) and other Australian national peak clinical bodies.</p> <p style="text-align:justify;">This unit applies to a range of workers within an education and care setting who are required to respond to a first aid emergency, including asthma and anaphylactic emergencies. This includes early childhood workers and educators who work with school age children in outside school hours care and vacation programs. </p>',
    total_course_duration = '',
    offshore_tuition_fee = '',
