UPDATE courses SET
    course_description = '<p style="text-align:justify;"> This unit describes the skills and knowledge required to perform peripheral intravenous cannulation on clients.</p> <p style="text-align:justify;"> This unit applies to registered enrolled nurses, registered Aboriginal and/or Torres Strait Islander health practitioners and emergency workers for whom peripheral intravenous cannulation is part of the job role. They may be working in hospitals, primary health care in rural remote locations, pathology services, out-of-hospital settings or in other allied health care environments.</p> <p style="text-align:justify;"> The extent of the practitioner’s role for peripheral intravenous cannulation may be subject to state/territory legislation and organisation policy, and competency should be demonstrated within the context of applicable legislation and organisation practice.</p> <p style="text-align:justify;"> The skills in this unit must be applied in accordance with Commonwealth and State/Territory legislation, Australian/New Zealand standards and industry codes of practice.</p>',
    total_course_duration = '',
    offshore_tuition_fee = '',
    entry_requirements = '',
    apply_form = 'https://www.leadcollege.edu.au/courses/perform-peripheral-intravenous-cannulation/',
    updated_at = NOW()
WHERE cricos_course_code = '';


UPDATE courses SET
    course_description = '<p style="text-align:justify;">This unit describes the skills and knowledge required to confirm collection requirements, prepare client and equipment, and perform routine blood collections using venous blood collection.</p> <p style="text-align:justify;">This unit applies to any individual for whom blood collection is part of the job role. They may be working in collection centres, in hospitals or in other health care environments.</p> <p style="text-align:justify;">This unit relates to collections from adults of varied ages and genders, adolescents and children over 5 years of age. It does not include collections from babies, neonates, arterial collections or collections made via artificial access devices such as central lines, peripherally inserted central catheter (PICC) lines, or intra venous (IV) catheter.</p> <p style="text-align:justify;">The skills in this unit must be applied in accordance with Commonwealth and State/Territory legislation, Australian/New Zealand standards and industry codes of practice.</p>',
    total_course_duration = '',
    offshore_tuition_fee = '',
    entry_requirements = '',
    apply_form = 'https://www.leadcollege.edu.au/courses/perform-venous-blood-collections/',
    updated_at = NOW()
WHERE cricos_course_code = '';


